// Test services slice 1: the staging-only catalog signing keys. COMMITTED EMPTY, and a release build (public or Enterprise) never has anything else: this file is generated by `packages/contracts/tools/catalog-flavor.ts`
// (the staging build path, and the worker Dockerfile's CATALOG_FLAVOR build argument), which writes the keys from `environments/service-catalog/staging-signing-key.json` for a staging flavor and the EMPTY list for a
// release flavor. So release code does not merely refuse to trust the key, it does not contain it. `scripts/release/build.ts` refuses a tree where this file or the compiled one holds anything.
import { type CatalogSigningKey } from "@rovara-code/contracts";

export const CATALOG_STAGING_ONLY_SIGNING_KEYS: readonly CatalogSigningKey[] = [];
